import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse(`{"title":"Engineering Delivery and Repository Structure","description":"Hearth's engineering principles, tech stack, repository layout, process model, testing and evaluation, observability, and release migration.","frontmatter":{"title":"Engineering Delivery and Repository Structure","description":"Hearth's engineering principles, tech stack, repository layout, process model, testing and evaluation, observability, and release migration.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/engineering.md","filePath":"en/delivery/engineering.md","lastUpdated":1793784691000}`),i={name:"en/delivery/engineering.md"};function r(o,e,l,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<p class="eyebrow">ENGINEERING</p><h1 id="engineering-delivery-and-repository-structure" tabindex="-1">Engineering Delivery and Repository Structure <a class="header-anchor" href="#engineering-delivery-and-repository-structure" aria-label="Permalink to &quot;Engineering Delivery and Repository Structure&quot;">​</a></h1><p class="lead">Engineering principles, recommended tech stack, repository layout, process model, data directory, CLI, Event Log, testing and evaluation, observability, and release migration.</p><h2 id="engineering-architecture-and-repository-structure" tabindex="-1">Engineering Architecture and Repository Structure <a class="header-anchor" href="#engineering-architecture-and-repository-structure" aria-label="Permalink to &quot;Engineering Architecture and Repository Structure&quot;">​</a></h2><h3 id="engineering-principles" tabindex="-1">Engineering Principles <a class="header-anchor" href="#engineering-principles" aria-label="Permalink to &quot;Engineering Principles&quot;">​</a></h3><ul><li><strong>Modular monolith first</strong>: do not introduce microservices early;</li><li><strong>Vertical slices first</strong>: every milestone must simultaneously include UI, persistent state, execution, verification, and recovery;</li><li><strong>The interface is the acceptance surface</strong>: capabilities that users cannot complete in the browser do not pass the stage exit;</li><li><strong>Single writer</strong>: the same State Root has only one write authority;</li><li><strong>Event sourcing</strong>: facts are written to the Event Log; UI/indexes are projections;</li><li><strong>Schema first</strong>: inputs, outputs, Effects, and Approvals all have versioned schemas;</li><li><strong>Adapter isolation</strong>: Codex, Connector, Browser, GUI, and Sandbox are all integrated through interfaces;</li><li><strong>Local first</strong>: data is local by default, and cloud resources are replaceable;</li><li><strong>Rollback-capable</strong>: databases, skills, configuration, and releases all have rollback paths;</li><li><strong>Observable</strong>: every task has a correlation id, trace, and cost attribution.</li></ul><h3 id="recommended-tech-stack" tabindex="-1">Recommended Tech Stack <a class="header-anchor" href="#recommended-tech-stack" aria-label="Permalink to &quot;Recommended Tech Stack&quot;">​</a></h3><p>The following are default recommendations, not an unchangeable religion:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Recommendation</th></tr></thead><tbody><tr><td>Language</td><td>TypeScript / Node.js 22+</td></tr><tr><td>Package management</td><td>pnpm</td></tr><tr><td>Monorepo</td><td>Turborepo or equivalent tooling</td></tr><tr><td>Long-running service</td><td>Node + Fastify/Hono</td></tr><tr><td>Database</td><td>SQLite WAL + migration</td></tr><tr><td>Schema</td><td>Zod / JSON Schema</td></tr><tr><td>Web</td><td>React + Vite + PWA</td></tr><tr><td>Real-time updates</td><td>SSE first, WebSocket when necessary</td></tr><tr><td>Browser</td><td>Playwright</td></tr><tr><td>Documents/data</td><td>Python sidecar + mature parsing libraries</td></tr><tr><td>Sandbox</td><td>Start with Docker, microVMs for untrusted tasks</td></tr><tr><td>Observability</td><td>OpenTelemetry + local logs/metrics</td></tr><tr><td>Testing and evaluation</td><td>Vitest/Playwright/contract testing/fault injection/task sets and benchmarks</td></tr><tr><td>Packaging</td><td>npm CLI + Docker Compose</td></tr></tbody></table><p>The reason for choosing TypeScript is that the frontend and backend share types, event protocols, and schemas, making it suitable for rapidly building a local Web and CLI; document/data-intensive processing is supplemented by a Python sidecar to fill in the ecosystem, without splitting the entire system into multilingual microservices.</p><h3 id="repository-layout" tabindex="-1">Repository Layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository Layout&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearth-os/</span></span>
<span class="line"><span>  apps/</span></span>
<span class="line"><span>    hearthd/              # Resident service: Gateway / Control / Harness</span></span>
<span class="line"><span>    web/                  # Task cards, approvals, artifacts, PWA</span></span>
<span class="line"><span>    cli/                  # hearth commands</span></span>
<span class="line"><span>    agentd/               # Device node (later)</span></span>
<span class="line"><span>  packages/</span></span>
<span class="line"><span>    core/                 # Domain model, state machine, error classification</span></span>
<span class="line"><span>    eventlog/             # Event Log, projections, migration</span></span>
<span class="line"><span>    harness/              # Ticket, Run, lease, outbox, recovery</span></span>
<span class="line"><span>    policy/               # Policy, Mandate, Capability, risk</span></span>
<span class="line"><span>    context/              # Context Compiler, Task Pack</span></span>
<span class="line"><span>    token/                # Token Governor, budget, attribution</span></span>
<span class="line"><span>    memory/               # Memory writes, retrieval, forgetting, sync</span></span>
<span class="line"><span>    evolution/            # Trajectories, skills, evaluation, promotion, rollback</span></span>
<span class="line"><span>    executors/</span></span>
<span class="line"><span>      native/</span></span>
<span class="line"><span>      codex/</span></span>
<span class="line"><span>      connector/</span></span>
<span class="line"><span>      browser/</span></span>
<span class="line"><span>      gui/</span></span>
<span class="line"><span>      document/</span></span>
<span class="line"><span>    connectors/           # email/calendar/docs/im/issue</span></span>
<span class="line"><span>    gateway/              # Channels, devices, notifications, identity</span></span>
<span class="line"><span>    execution/            # Sandbox Provider, egress, Broker</span></span>
<span class="line"><span>    artifacts/            # Artifacts, hashes, versions, verification</span></span>
<span class="line"><span>    shared/               # schema, types, utilities</span></span>
<span class="line"><span>  sidecars/</span></span>
<span class="line"><span>    docdata/              # Python document/data pipeline and pytest</span></span>
<span class="line"><span>  tests/</span></span>
<span class="line"><span>    contract/</span></span>
<span class="line"><span>    integration/</span></span>
<span class="line"><span>    e2e/</span></span>
<span class="line"><span>    slices/</span></span>
<span class="line"><span>    fault/</span></span>
<span class="line"><span>    replay/</span></span>
<span class="line"><span>    security/</span></span>
<span class="line"><span>    performance/</span></span>
<span class="line"><span>    fixtures/</span></span>
<span class="line"><span>    helpers/</span></span>
<span class="line"><span>  evals/</span></span>
<span class="line"><span>    suites/</span></span>
<span class="line"><span>    scorers/</span></span>
<span class="line"><span>    baselines/</span></span>
<span class="line"><span>  docs/</span></span>
<span class="line"><span>    adr/</span></span>
<span class="line"><span>    architecture/</span></span>
<span class="line"><span>  docker/</span></span></code></pre></div><h3 id="process-model" tabindex="-1">Process Model <a class="header-anchor" href="#process-model" aria-label="Permalink to &quot;Process Model&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearth CLI / Web / Mobile</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ▼</span></span>
<span class="line"><span>       hearthd</span></span>
<span class="line"><span>  ├─ Gateway</span></span>
<span class="line"><span>  ├─ Control Plane</span></span>
<span class="line"><span>  ├─ Durable Harness</span></span>
<span class="line"><span>  ├─ Token Governor / Context Compiler</span></span>
<span class="line"><span>  ├─ Executor Supervisor</span></span>
<span class="line"><span>  ├─ Event Log / projections</span></span>
<span class="line"><span>  ├─ Sandbox Provider client</span></span>
<span class="line"><span>  ├─ Credential Broker</span></span>
<span class="line"><span>  └─ Effect Dispatcher</span></span>
<span class="line"><span>          │</span></span>
<span class="line"><span>          ├─ Codex adapter</span></span>
<span class="line"><span>          ├─ Browser worker</span></span>
<span class="line"><span>          ├─ Connector workers</span></span>
<span class="line"><span>          ├─ Document/Data sidecar</span></span>
<span class="line"><span>          └─ Device agentd (later)</span></span></code></pre></div><p>All Executors connect through a unified protocol and never write directly to the primary database. SQLite is written by the single <code>hearthd</code> process; Executors receive work through RPC/Task queues.</p><h3 id="data-directory" tabindex="-1">Data Directory <a class="header-anchor" href="#data-directory" aria-label="Permalink to &quot;Data Directory&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.hearth/</span></span>
<span class="line"><span>  state.db                # Event Log + projections</span></span>
<span class="line"><span>  artifacts/              # Content-addressed artifacts</span></span>
<span class="line"><span>  workspaces/             # Temporary and project workspaces</span></span>
<span class="line"><span>  config/</span></span>
<span class="line"><span>    policy.yaml</span></span>
<span class="line"><span>    connections.yaml</span></span>
<span class="line"><span>  secrets/                # Encrypted credentials or Broker pointers</span></span>
<span class="line"><span>  logs/</span></span>
<span class="line"><span>  backups/</span></span>
<span class="line"><span>  devices/</span></span></code></pre></div><p>Minimize permissions on sensitive directories; encrypt backups; device sync transmits only the necessary projections and Artifact references.</p><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hearth init</span></span>
<span class="line"><span>hearth run &quot;compile this week&#39;s competitor updates and generate a weekly report draft&quot;</span></span>
<span class="line"><span>hearth status</span></span>
<span class="line"><span>hearth inbox</span></span>
<span class="line"><span>hearth approve &lt;id&gt;</span></span>
<span class="line"><span>hearth artifacts</span></span>
<span class="line"><span>hearth memory search &quot;Project A decisions&quot;</span></span>
<span class="line"><span>hearth memory forget &lt;id&gt;</span></span>
<span class="line"><span>hearth doctor</span></span>
<span class="line"><span>hearth export</span></span></code></pre></div><p>CLI output supports both human-readable and JSON modes, making it convenient for scripts and automated tests.</p><h3 id="event-log-and-projections" tabindex="-1">Event Log and Projections <a class="header-anchor" href="#event-log-and-projections" aria-label="Permalink to &quot;Event Log and Projections&quot;">​</a></h3><ul><li>Events are append-only and are not updated in place;</li><li>Each Event has schemaVersion, correlationId, and causationId;</li><li>Task state, inbox, Artifacts, and costs are all projections;</li><li>Projections can be rebuilt;</li><li>Event hash chains or equivalent integrity verification;</li><li>Large content is stored in Artifacts, and Events store only references;</li><li>Migrations must remain compatible with old Events;</li><li>Event replay must not produce external side effects.</li></ul><h3 id="tasks-and-leases" tabindex="-1">Tasks and Leases <a class="header-anchor" href="#tasks-and-leases" aria-label="Permalink to &quot;Tasks and Leases&quot;">​</a></h3><ul><li>Each Ticket has at most one active Assignment at any given time;</li><li>Leases carry a fencing token;</li><li>Executors validate the fencing token before writing;</li><li>When a device goes offline, its lease expires and the Task can be reassigned;</li><li>Reassignment must not duplicate external Effects;</li><li>Task state transitions have explicit Events and conditions;</li><li>Subtasks inherit the parent Task&#39;s budget and permission intersection.</li></ul><h3 id="testing-and-evaluation-system" tabindex="-1">Testing and Evaluation System <a class="header-anchor" href="#testing-and-evaluation-system" aria-label="Permalink to &quot;Testing and Evaluation System&quot;">​</a></h3><p>Testing is not an appendix to feature work; it is part of every increment&#39;s deliverable. Every <code>Dx.y</code> increment must ship implementation, slice E2E, failure paths, and regression tests together. &quot;Feature first, tests later&quot; is not acceptable.</p><h4 id="two-principles" tabindex="-1">Two Principles <a class="header-anchor" href="#two-principles" aria-label="Permalink to &quot;Two Principles&quot;">​</a></h4><ul><li><strong>Tests are not evaluations.</strong> A test is a deterministic pass/fail gate; an evaluation (eval) is a statistical measure of quality, such as verified task success, citation accuracy, token cost, or human minutes. Both are required, but they must not be mixed into one CI gate. See <a href="/hearth-os/en/architecture/evaluation.html">Evaluation System</a> for task sets, metrics, and statistical discipline.</li><li><strong>Test code ships in the same PR as the feature.</strong> Every increment must deliver implementation, slice E2E, failure paths, and regression tests together. Do not defer testing to a later phase.</li></ul><h4 id="the-nine-testing-layers" tabindex="-1">The Nine Testing Layers <a class="header-anchor" href="#the-nine-testing-layers" aria-label="Permalink to &quot;The Nine Testing Layers&quot;">​</a></h4><ol><li><strong>Unit tests</strong>: pure logic, including state machines, Task/Ticket transitions, budget calculations, permission decisions, verifiers, error classification, and Context Compiler trimming rules. Use Vitest for TypeScript and pytest for the Python sidecar.</li><li><strong>Contract tests</strong>: test boundaries, not internal implementation. Focus on Executors, Connectors, Sandbox Providers, the Credential Broker, and the Effect Dispatcher. The Codex adapter must honor the unified <code>TaskPack → Result</code> contract; email connectors must honor the <code>Source/Effect</code>, idempotency, and Receipt contracts. Contract tests are the main defense against &quot;one behavior in mocks, another in production.&quot;</li><li><strong>Integration tests</strong>: use a real temporary SQLite database to test the Event Log, projection rebuilds, migrations, outbox, leases, fencing tokens, duplicate delivery, and crash recovery. Do not mock the database here, because persistent behavior is exactly what must be verified.</li><li><strong>Vertical slice E2E</strong>: every <code>Dx.y</code> has a browser acceptance path covering task creation, status, approval, artifact retrieval, and failure recovery. Stage 0 uses a fake executor to exercise the prototype; Stage 1 starts using a real Codex slice. This is the most important test category for the project.</li><li><strong>Fault injection</strong>: inject <code>kill -9</code> at the queueing, execution, artifact-write, and approval-wait points, then cover network loss, timeouts, full disk, duplicate delivery, device offline, and clock skew. Acceptance should map directly to stage gates: zero duplicate external side effects and the target recovery rate.</li><li><strong>Replay and determinism tests</strong>: replay recorded event streams to verify that projections rebuild, old events can be upgraded, and replay does not produce external side effects. UI state must also be recoverable from the event stream rather than depending on in-memory objects.</li><li><strong>Security tests</strong>: cover privilege escalation, approval replay, nonce/expiry handling, secret leakage, prompt injection, untrusted web content, SSRF/egress, cross-account isolation, and device revocation. Every new permission must ship both &quot;allow&quot; and &quot;deny&quot; tests.</li><li><strong>Performance and long-run tests</strong>: cover startup time, task-creation latency, query latency, long-running tasks, concurrency limits, memory leaks, and disk growth. Benchmark scripts and baseline results can be committed, but do not hard-gate every PR on early thresholds.</li><li><strong>Evaluation sets (evals)</strong>: build representative tasks, success/failure samples, scoring rules, and human review per task family. Evals focus on task success, citation traceability, human minutes, token/cost, and interruption counts. Memory and evolution stages also require dedicated evaluations for &quot;forgetting propagation,&quot; &quot;no permission expansion,&quot; and &quot;Shadow/Canary rollback.&quot;</li></ol><h4 id="repository-layout-1" tabindex="-1">Repository Layout <a class="header-anchor" href="#repository-layout-1" aria-label="Permalink to &quot;Repository Layout&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/</span></span>
<span class="line"><span>  hearthd/src/**/*.test.ts</span></span>
<span class="line"><span>  web/src/**/*.test.tsx</span></span>
<span class="line"><span>  cli/test/*.test.ts</span></span>
<span class="line"><span>packages/</span></span>
<span class="line"><span>  core/test/</span></span>
<span class="line"><span>  eventlog/test/</span></span>
<span class="line"><span>  harness/test/</span></span>
<span class="line"><span>  policy/test/</span></span>
<span class="line"><span>  executors/*/test/</span></span>
<span class="line"><span>tests/</span></span>
<span class="line"><span>  contract/</span></span>
<span class="line"><span>  integration/</span></span>
<span class="line"><span>  e2e/</span></span>
<span class="line"><span>  slices/D1.1/</span></span>
<span class="line"><span>  fault/</span></span>
<span class="line"><span>  replay/</span></span>
<span class="line"><span>  security/</span></span>
<span class="line"><span>  performance/</span></span>
<span class="line"><span>  fixtures/</span></span>
<span class="line"><span>  helpers/</span></span>
<span class="line"><span>evals/</span></span>
<span class="line"><span>  suites/</span></span>
<span class="line"><span>  scorers/</span></span>
<span class="line"><span>  baselines/</span></span>
<span class="line"><span>sidecars/docdata/tests/</span></span></code></pre></div><p>Keep unit tests close to the source. Put cross-module, cross-process, and stage-acceptance tests under the root <code>tests/</code> directory. Keep <code>evals/</code> separate from ordinary tests.</p><h4 id="test-code-that-must-be-committed" tabindex="-1">Test Code That Must Be Committed <a class="header-anchor" href="#test-code-that-must-be-committed" aria-label="Permalink to &quot;Test Code That Must Be Committed&quot;">​</a></h4><ul><li>All <code>.test.ts</code>, <code>.test.tsx</code>, <code>*.spec.ts</code>, and <code>test_*.py</code> files.</li><li>Contract tests, fixtures, fake servers, fake executors, fake Codex JSONL cassettes, and fake effect sinks.</li><li>Synthetic or desensitized test documents, emails, calendar data, and web samples.</li><li>Database migration tests and old-version fixtures.</li><li>Eval task definitions, scorers, and baseline metrics.</li><li>CI configuration, test runner scripts, and test-data generation scripts.</li><li>Security test cases and fault-injection scenarios.</li><li>Small, meaningful golden files such as structured results, diffs, and JSON schemas.</li></ul><h4 id="do-not-commit" tabindex="-1">Do Not Commit <a class="header-anchor" href="#do-not-commit" aria-label="Permalink to &quot;Do Not Commit&quot;">​</a></h4><ul><li>Real email, calendar, or document data, cookies, tokens, refresh tokens, or API keys.</li><li>Real user data, real Codex session records, or real email bodies.</li><li>Large test videos, screenshots, databases, coverage reports, or test logs.</li><li>Temporary generated artifacts and caches.</li><li>Absolute paths or developer-machine configuration that only works locally.</li></ul><p>For external dependencies such as Codex, commit a <strong>fake Codex CLI</strong> that emits the agreed JSONL protocol. Run real Codex only in nightly or manual smoke tests. This keeps PR tests stable and inexpensive without drifting from the real protocol.</p><h4 id="three-ci-tiers" tabindex="-1">Three CI Tiers <a class="header-anchor" href="#three-ci-tiers" aria-label="Permalink to &quot;Three CI Tiers&quot;">​</a></h4><ul><li><strong>Required on PRs</strong>: unit + contract + integration + slice E2E with the fake executor, targeting under 10 minutes.</li><li><strong>Nightly</strong>: fault injection, security tests, performance, and real Codex/connector smoke tests.</li><li><strong>Release</strong>: full suite + migration + install/backup/restore + stage-exit acceptance.</li></ul><h4 id="five-hard-rules" tabindex="-1">Five Hard Rules <a class="header-anchor" href="#five-hard-rules" aria-label="Permalink to &quot;Five Hard Rules&quot;">​</a></h4><ul><li>Every bug fix ships with a regression test.</li><li>Every new event schema ships with migration and old-event compatibility tests.</li><li>Every new external side effect ships with idempotency and duplicate-delivery tests.</li><li>Every new permission ships with denial-path tests.</li><li>Every new executor or connector ships with contract, timeout/cancellation, and failure-classification tests.</li></ul><p>The goal is not test count. It is to guarantee that <strong>when Hearth says &quot;the task is complete,&quot; tests can prove it; when Hearth says &quot;it can recover,&quot; fault injection can prove it.</strong></p><h3 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h3><ul><li>Each Task/Run has a trace id;</li><li>Each model call records the model, tokens, cost, and latency;</li><li>Each tool call records the parameter hash, result status, and resources;</li><li>Each external side effect records an idempotency key and a Receipt;</li><li>The UI displays only the Events that users need;</li><li>Detailed information is retained in a local audit view;</li><li>Logs are automatically redacted;</li><li>Metrics are used for routing and evaluation, not for manipulating users.</li></ul><h3 id="release-and-migration" tabindex="-1">Release and Migration <a class="header-anchor" href="#release-and-migration" aria-label="Permalink to &quot;Release and Migration&quot;">​</a></h3><ul><li>Version schemas and APIs;</li><li>Database migrations are forward-compatible;</li><li>Executor versions are pinned;</li><li>Skills are versioned;</li><li>Run evaluations and fault injection before release;</li><li>Support rollback to the previous stable version;</li><li>Upgrades do not break historical Events and Artifacts;</li><li>Users can export and migrate.</li><li>Each increment retains a rollback-capable version; recovery must not rely solely on rebuilding the environment.</li></ul><hr>`,49)])])}const g=a(i,[["render",r]]);export{h as __pageData,g as default};
